mapper.update:
        DECLARE
            v_count NUMBER;
        BEGIN
            SELECT COUNT(*)
              INTO v_count
              FROM USER_TAB_COLUMNS
             WHERE TABLE_NAME = 'EVENTS'
               AND COLUMN_NAME = 'EVENT_TYPE';

            IF v_count = 0 THEN
                EXECUTE IMMEDIATE 'ALTER TABLE EVENTS ADD (EVENT_TYPE VARCHAR2(30) DEFAULT ''APPOINTMENT'' NOT NULL)';
            END IF;
        END;

        DECLARE
            v_count NUMBER;
        BEGIN
            SELECT COUNT(*) INTO v_count FROM USER_TABLES WHERE TABLE_NAME = 'EVENT_ATTENDEES';
            IF v_count = 0 THEN
                EXECUTE IMMEDIATE 'CREATE TABLE EVENT_ATTENDEES (EA_ID NUMBER(20) NOT NULL, EVENT_ID NUMBER(10) NOT NULL, USER_ID NUMBER(10) NOT NULL, ST_CODE VARCHAR2(10) DEFAULT ''WT'' NOT NULL, CREATED_AT DATE DEFAULT SYSDATE NOT NULL, CONSTRAINT PK_EVENT_ATTENDEES PRIMARY KEY (EA_ID), CONSTRAINT UK_EVENT_ATTENDEE_USER UNIQUE (EVENT_ID, USER_ID), CONSTRAINT FK_EA_EVENT FOREIGN KEY (EVENT_ID) REFERENCES EVENTS(EVENT_ID) ON DELETE CASCADE, CONSTRAINT FK_EA_USER FOREIGN KEY (USER_ID) REFERENCES USERS(USER_ID))';
            END IF;

            SELECT COUNT(*) INTO v_count FROM USER_SEQUENCES WHERE SEQUENCE_NAME = 'SEQ_EA_ID';
            IF v_count = 0 THEN
                EXECUTE IMMEDIATE 'CREATE SEQUENCE SEQ_EA_ID START WITH 1 INCREMENT BY 1 NOCACHE';
            END IF;
        END;

mapper.select:
SELECT COUNT(1)
  FROM EVENTS e
 WHERE e.EVENT_ID = #{eventId}
   AND (
        e.USER_ID = #{userId}
     OR EXISTS (
            SELECT 1
              FROM CONTENT_SHARES s
             WHERE s.CONTENT_TYPE = 'CALENDAR'
               AND s.CONTENT_ID = e.EVENT_ID
               AND s.ACTIVE_YN = 'Y'
               AND NVL(s.SHARE_STATUS, 'ACCEPTED') = 'ACCEPTED'
               AND UPPER(NVL(s.PERMISSION_TYPE, 'VIEW')) = 'EDIT'
               AND (s.EXPIRES_AT IS NULL OR s.EXPIRES_AT >= SYSDATE)
               AND (
                    (s.TARGET_TYPE = 'USER' AND s.TARGET_ID = #{userId})
                 OR (s.TARGET_TYPE = 'WS' AND EXISTS (
                        SELECT 1 FROM WS_MEMBERS wm
                         WHERE wm.WS_ID = s.TARGET_ID
                           AND wm.USER_ID = #{userId}
                    ))
                 OR (s.TARGET_TYPE = 'PROJ' AND EXISTS (
                        SELECT 1 FROM PROJ_MEMBERS pm
                         WHERE pm.PROJ_ID = s.TARGET_ID
                           AND pm.USER_ID = #{userId}
                    ))
               )
        )
     OR (NVL(e.ITEM_TYPE, 'PRIVATE') = 'WS' AND e.WS_ID IS NOT NULL AND (
            EXISTS (SELECT 1 FROM WORKSPACES w WHERE w.WS_ID = e.WS_ID AND w.OWNER_ID = #{userId})
         OR EXISTS (SELECT 1 FROM WS_MEMBERS wm2
                      WHERE wm2.WS_ID = e.WS_ID
                        AND wm2.USER_ID = #{userId}
                        AND UPPER(NVL(wm2.WS_ROLE, 'MEMBER')) IN ('ADMIN','OWNER','LEADER','MANAGER'))
        ))
     OR (NVL(e.ITEM_TYPE, 'PRIVATE') = 'PROJ' AND e.PROJ_ID IS NOT NULL AND (
            EXISTS (SELECT 1 FROM PROJECTS p WHERE p.PROJ_ID = e.PROJ_ID AND p.LEADER_ID = #{userId})
         OR EXISTS (SELECT 1 FROM PROJ_MEMBERS pm2
                      WHERE pm2.PROJ_ID = e.PROJ_ID
                        AND pm2.USER_ID = #{userId}
                        AND UPPER(NVL(pm2.PROJ_ROLE, 'MEMBER')) IN ('ADMIN','OWNER','LEADER','MANAGER','PM'))
        ))
   )

SELECT COUNT(1)
