         OR EXISTS (SELECT 1 FROM WS_MEMBERS wm
                      WHERE wm.WS_ID = e.WS_ID
                        AND wm.USER_ID = #{userId}
                        AND UPPER(NVL(wm.WS_ROLE, 'MEMBER')) IN ('ADMIN','OWNER','LEADER','MANAGER'))
        ))
     OR (NVL(e.ITEM_TYPE, 'PRIVATE') = 'PROJ' AND e.PROJ_ID IS NOT NULL AND (
            EXISTS (SELECT 1 FROM PROJECTS p WHERE p.PROJ_ID = e.PROJ_ID AND p.LEADER_ID = #{userId})
         OR EXISTS (SELECT 1 FROM PROJ_MEMBERS pm
                      WHERE pm.PROJ_ID = e.PROJ_ID
                        AND pm.USER_ID = #{userId}
                        AND UPPER(NVL(pm.PROJ_ROLE, 'MEMBER')) IN ('ADMIN','OWNER','LEADER','MANAGER','PM'))
        ))
   )

